INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Trump acquire Greenland before 2027?', 'This market will resolve to "Yes" if the United States officially announces that Greenland will come under US sovereignty by December 31, 2026, 11:59 PM ET. Otherwise this market will resolve to "No". Sovereignty is defined as the transfer of the majority of the territory of Greenland from its current status as an autonomous territory within the Kingdom of Denmark to being under the formal governance or jurisdiction of the United States, either as a state, territory, or other classification with', 'politics', 'active', 678745.52, 16951008.21, 679245.52, 16951508.21);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Naftali Bennett be the next Prime Minister of Israel?', 'Legislative elections are schedule to be held in Israel on October 27, 2026. This market will resolve to the next individual who is officially appointed and sworn in as Prime Minister of Israel following the 2026 parliamentary election. If an election is called early, this market will immediately resolve to the individual who is officially appointed and sworn in after that election. To count for resolution, the individual must be formally sworn in. Any interim or caretaker Prime Minister will no', 'politics', 'active', 79639.16, 1368345.52, 80139.16, 1368845.52);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('New "Stranger Things" episode released by December 31? ', 'This market will resolve to "Yes" if Netflix officially releases a new episode of Stranger Things (i.e., an episode that was not previously available to stream on Netflix) between market creation and December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No". For the purposes of this market, an “episode” must be listed as a distinct episode of Stranger Things on Netflix and be playable for general subscribers in the United States. A behind-the-scenes featurette, documentary, tra', 'entertainment', 'active', 24788.04, 526057.34, 25288.04, 526557.34);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the Fed decrease interest rates by 25 bps after the September 2026 meeting?', 'The FED interest rates are defined in this market by the upper bound of the target federal funds range. The decisions on the target federal funds range are made by the Federal Open Market Committee (FOMC) meetings. This market will resolve to the amount of basis points the upper bound of the target federal funds rate is changed by versus the level it was prior to the Federal Reserve''s September 2026 meeting. If the target federal funds rate is changed to a level not expressed in the displayed o', 'politics', 'active', 45265.33, 3890850.68, 45765.33, 3891350.68);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('US obtains Iranian enriched uranium by December 31?', 'This market will resolve to “Yes” if the US government or military officially announces or confirms that it has gained possession of any quantity of enriched uranium previously controlled by Iran by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to “No”. “Possession” means that the United States has actual physical custody or control of the enriched uranium, whether held within U.S. territory or elsewhere. Announcements of deals, agreements, commitments, or plans under which', 'politics', 'active', 79394.29, 979196.24, 79894.29, 979696.24);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Williams be the 2026 F1 Constructors'' Champion?', 'This market will resolve according to the winner of the Constructors’ Championship for the 2026 F1 season. This market will resolve as soon as the official results of the final scheduled race of the 2026 F1 season are known. In the case of a tie between multiple teams, this market will resolve according to the tiebreak procedure used by F1 to determine the 2026 F1 Constructors’ champion. If at any point it becomes impossible for a listed team to win the 2026 F1 Constructors’ Championship based o', 'sports', 'active', 19040.87, 1885045.98, 19540.87, 1885545.98);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Harry Kane win the 2026 Ballon d''Or?', 'This market will resolve according to the winner of the 2026 Ballon d’Or. If no 2026 Ballon d’Or winner is declared by December 31, 2026, 11:59 PM ET, this market will resolve to "Other". The primary resolution source for this market is official information from France Football (https://www.francefootball.fr/).', 'sports', 'active', 974895.57, 664962.41, 975395.57, 665462.41);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Bitcoin hit $150k by December 31, 2026?', 'This market will immediately resolve to "Yes" if any Binance 1 minute candle for Bitcoin (BTC/USDT) has a final "High" price equal to or greater than the price specified in the title by 11:59PM ET on the date specified in the title. Otherwise, this market will resolve to "No." The resolution source for this market is Binance, specifically the BTC/USDT "High" prices available at https://www.binance.com/en/trade/BTC_USDT, with the chart settings on "1m" for one-minute candles selected on the top b', 'crypto', 'active', 39069.54, 1331791.35, 39569.54, 1332291.35);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Israel closes its airspace by August 31?', 'This market will resolve to “Yes” if Israel initiates a major closure of its airspace by the specified date, 11:59 PM ET. Otherwise, this market will resolve to “No”. A “major closure” is defined as a broad closure, cancellation, or complete suspension of commercial aviation across the entirety of Israeli civilian airspace or a region encompassing a majority of Israeli civilian airspace, including commercial flights transiting, arriving in, and departing from that airspace. A qualifying closure ', 'politics', 'active', 40388.55, 434770.82, 40888.55, 435270.82);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the Iranian regime fall before 2027?', 'This market will resolve to "Yes" if the Islamic Republic of Iran’s current ruling regime is overthrown, collapsed, or otherwise ceases to govern by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to “No”. This requires a broad consensus of reporting indicating that core structures of the Islamic Republic (e.g. the office of the Supreme Leader, the Guardian Council, IRGC control under clerical authority) have been dissolved, incapacitated, or replaced by a fundamentally diffe', 'politics', 'active', 799999.22, 11507681.12, 800499.22, 11508181.12);